CREATE TABLE ZPAPER ( Z_PK INTEGER PRIMARY KEY, Z_ENT INTEGER, Z_OPT INTEGER, ZRATING INTEGER, ZYEAR INTEGER, ZDATEADDED TIMESTAMP, ZABSTRACT VARCHAR, ZADDRESS VARCHAR, ZBIBTEXKEY VARCHAR, ZBOOKTITLE VARCHAR, ZCHAPTER VARCHAR, ZDOI VARCHAR, ZEDITION VARCHAR, ZEPRINT VARCHAR, ZEPRINTCLASS VARCHAR, ZEPRINTTYPE VARCHAR, ZEVENTDATE VARCHAR, ZEVENTTITLE VARCHAR, ZHOWPUBLISHED VARCHAR, ZINSTITUTION VARCHAR, ZISBN VARCHAR, ZISSUE VARCHAR, ZJOURNAL VARCHAR, ZLANGUAGE VARCHAR, ZMONTH VARCHAR, ZNOTES VARCHAR, ZORGANIZATION VARCHAR, ZPAGES VARCHAR, ZPAPERTYPE VARCHAR, ZPUBSTATE VARCHAR, ZPUBLISHER VARCHAR, ZSCHOOL VARCHAR, ZSERIES VARCHAR, ZSUBTITLE VARCHAR, ZTITLE VARCHAR, ZTYPE VARCHAR, ZURL VARCHAR, ZURLDATE VARCHAR, ZVENUE VARCHAR, ZVOLUME VARCHAR, ZID BLOB, ZAUTHORS BLOB, ZEDITORS BLOB, ZTRANSLATORS BLOB, ZEXTRAFIELDSDATA BLOB, ZPDFBOOKMARK BLOB );
