CREATE TABLE ZPDFANNOTATIONITEM ( Z_PK INTEGER PRIMARY KEY, Z_ENT INTEGER, Z_OPT INTEGER, ZPAGEINDEX INTEGER, ZSORTORDER INTEGER, ZPAPER INTEGER, ZBOUNDSHEIGHT FLOAT, ZBOUNDSWIDTH FLOAT, ZBOUNDSX FLOAT, ZBOUNDSY FLOAT, ZCOLORHEX VARCHAR, ZCONTENTS VARCHAR, ZPAGELABEL VARCHAR, ZTEXT VARCHAR, ZTYPE VARCHAR, ZRENDEREDIMAGEDATA BLOB );
